import sys

N = int(sys.stdin.read().split()[0])
MOD = 10**9 + 7
if N <= 11:
    cells = [[0] * N for _ in range(2)]

    def go(pos):
        if pos == 2 * N:
            return 1
        r, c = divmod(pos, N)
        total = go(pos + 1)
        if (c == 0 or not cells[r][c - 1]) and (r == 0 or not cells[0][c]):
            cells[r][c] = 1
            total += go(pos + 1)
            cells[r][c] = 0
        return total

    print(go(0) % MOD)
else:
    pats = [(a, b) for a in (0, 1) for b in (0, 1) if not (a and b)]
    dp = {p: 1 for p in pats}
    for _ in range(N - 1):
        dp = {p: sum(v for q, v in dp.items() if not (p[0] and q[0]) and not (p[1] and q[1])) % MOD for p in pats}
    print(sum(dp.values()) % MOD)

